public with sharing class ContactDomainService {
    /**
     * Groups contacts associated with the provided account IDs by the domain of their email address.
     * 
     * @param accountIds A set of Account IDs to filter contacts.
     * @return A map where keys are lower-cased email domains and values are lists of corresponding contacts.
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> domainMap = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return domainMap;
        }

        // Query contacts for the given accounts that have an email address.
        // Respects sharing via 'with sharing' class definition.
        for (Contact con : [
            SELECT Id, Email, AccountId 
            FROM Contact 
            WHERE AccountId IN :accountIds 
            AND Email != null
        ]) {
            // Extract the domain part of the email address.
            // substringAfter returns an empty string if the delimiter is not found,
            // but since we check contains('@'), we ensure a domain part exists.
            if (con.Email.contains('@')) {
                String domain = con.Email.substringAfter('@').toLowerCase();

                if (!domainMap.containsKey(domain)) {
                    domainMap.put(domain, new List<Contact>());
                }
                domainMap.get(domain).add(con);
            }
        }

        return domainMap;
    }
}
