public class OrderPayloadParser {

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines = new List<Line>();
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is null or blank');
        }

        Map<String, Object> root;
        try {
            Object untyped = JSON.deserializeUntyped(body);
            if (!(untyped instanceof Map<String, Object>)) {
                throw new PayloadException('JSON is not an object');
            }
            root = (Map<String, Object>) untyped;
        } catch (Exception e) {
            if (e instanceof PayloadException) throw e;
            throw new PayloadException('Invalid JSON: ' + e.getMessage());
        }

        Order order = new Order();

        // Order Number
        Object numObj = root.get('number');
        if (numObj == null || String.valueOf(numObj).trim() == '') {
            throw new PayloadException('Missing or blank order number');
        }
        order.orderNumber = String.valueOf(numObj);

        // Order Date
        Object dateObj = root.get('date');
        if (dateObj != null) {
            try {
                order.orderDate = Date.valueOf((String) dateObj);
            } catch (Exception e) {
                // Date format not specified for exception, but usually expected yyyy-MM-dd
                // Prompt implies we just parse it.
            }
        }

        // Currency
        Object currObj = root.get('currency');
        if (currObj != null) {
            order.currencyCode = String.valueOf(currObj);
        }

        // Customer
        Object customerObj = root.get('customer');
        if (customerObj instanceof Map<String, Object>) {
            Map<String, Object> customerMap = (Map<String, Object>) customerObj;
            order.customerEmail = (String) customerMap.get('email');
        }

        // Lines
        Object linesObj = root.get('lines');
        Decimal totalOrderAmount = Decimal.valueOf(0);

        if (linesObj instanceof List<Object>) {
            List<Object> linesList = (List<Object>) linesObj;
            for (Object lineItem : linesList) {
                if (!(lineItem instanceof Map<String, Object>)) continue;
                Map<String, Object> lineMap = (Map<String, Object>) lineItem;

                Line line = new Line();

                // SKU
                Object skuObj = lineMap.get('sku');
                if (skuObj == null) {
                    throw new PayloadException('Line missing sku');
                }
                line.sku = String.valueOf(skuObj);

                // Quantity
                Object qtyObj = lineMap.get('quantity');
                if (qtyObj == null) {
                    throw new PayloadException('Line missing quantity');
                }
                Integer qty = safeInteger(qtyObj);
                if (qty == null || qty <= 0) {
                    throw new PayloadException('Line quantity must be positive');
                }
                line.quantity = qty;

                // Unit Price
                Object priceObj = lineMap.get('unitPrice');
                if (priceObj == null) {
                    throw new PayloadException('Line missing unitPrice');
                }
                Decimal price = safeDecimal(priceObj);
                if (price == null || price < 0) {
                    throw new PayloadException('Line unitPrice cannot be negative');
                }
                line.unitPrice = price;

                // Discount
                Object discObj = lineMap.get('discount');
                Decimal disc = (discObj == null) ? Decimal.valueOf(0) : safeDecimal(discObj);
                line.discount = disc;

                // Line Total = quantity * unitPrice * (1 - discount)
                Decimal lineCalc = Decimal.valueOf(qty) * price * (Decimal.valueOf(1).subtract(disc));
                line.lineTotal = lineCalc.setScale(2, System.RoundingMode.HALF_UP);

                order.lines.add(line);
                totalOrderAmount = totalOrderAmount.add(line.lineTotal);
            }
        }

        order.total = totalOrderAmount;
        return order;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines != null ? order.lines.size() : 0);
        ack.put('total', order.total);
        return JSON.serialize(ack);
    }

    private static Decimal safeDecimal(Object obj) {
        if (obj == null) return null;
        try {
            return Decimal.valueOf(String.valueOf(obj));
        } catch (Exception e) {
            return null;
        }
    }

    private static Integer safeInteger(Object obj) {
        if (obj == null) return null;
        try {
            return Integer.valueOf(Decimal.valueOf(String.valueOf(obj)).intValue());
        } catch (Exception e) {
            return null;
        }
    }
}
