public with sharing class LeadImportService {

    /**
     * Result object containing the outcomes of the lead import process.
     */
    public class ImportResult {
        public Integer successCount = 0;                // number of leads inserted
        public List<Id> insertedIds = new List<Id>();  // Ids of the inserted leads, in input order
        public Map<Integer, String> errorsByIndex = new Map<Integer, String>(); // input position (0-based) -> error message
    }

    /**
     * Imports a list of leads, ensuring LeadSource is set and duplicate emails within the batch are handled.
     * 
     * @param leads The list of Lead records to import.
     * @return An ImportResult containing the success count, inserted IDs, and a map of errors by original index.
     */
    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Lead> leadsToInsert = new List<Lead>();
        List<Integer> originalIndices = new List<Integer>();
        Set<String> seenEmails = new Set<String>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];

            // Skip processing for null elements in the list if they occur
            if (lead == null) {
                result.errorsByIndex.put(i, 'Lead record is null');
                continue;
            }

            // Rule: Set LeadSource to 'Web' on every lead where it is blank.
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }

            // Rule: Handle duplicate emails within one call (case-insensitive, trimmed).
            if (String.isNotBlank(lead.Email)) {
                String normalizedEmail = lead.Email.trim().toLowerCase();
                if (seenEmails.contains(normalizedEmail)) {
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalizedEmail);
                    continue;
                }
                seenEmails.add(normalizedEmail);
            }

            leadsToInsert.add(lead);
            originalIndices.add(i);
        }

        // Rule: Use a single DML statement per call.
        if (!leadsToInsert.isEmpty()) {
            Database.SaveResult[] saveResults = Database.insert(leadsToInsert, false);

            for (Integer j = 0; j < saveResults.size(); j++) {
                Database.SaveResult sr = saveResults[j];
                Integer originalIdx = originalIndices[j];

                if (sr.isSuccess()) {
                    result.successCount++;
                    result.insertedIds.add(sr.getId());
                } else {
                    // Rule: For a lead the database rejects, the error is the messages joined with '; '.
                    List<String> errors = new List<String>();
                    for (Database.Error err : sr.getErrors()) {
                        errors.add(err.getMessage());
                    }
                    result.errorsByIndex.put(originalIdx, String.join(errors, '; '));
                }
            }
        }

        return result;
    }
}
