public class PicklistService {

    /**
     * Represents a picklist option containing the API value, display label, 
     * and whether it is the default value for the field.
     */
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    /**
     * Custom exception thrown when invalid object or field names are provided,
     * or when the specified field is not a picklist.
     */
    public class PicklistServiceException extends Exception {}

    /**
     * Retrieves the active picklist options for a given object and field.
     * 
     * @param objectApiName The API name of the SObject (case-insensitive).
     * @param fieldApiName The API name of the field (case-insensitive).
     * @return A list of active picklist options in the order defined on the field.
     * @throws PicklistServiceException if inputs are blank, the object/field doesn't exist, 
     *                                  or the field is not a picklist.
     */
    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object and field API names must be provided.');
        }

        try {
            // 1. Resolve Object API Name (Case-Insensitive)
            SObjectType sObjectType;
            Map<String, SObjectType> globalDescribe = Schema.getGlobalDescribe();
            sObjectType = globalDescribe.get(objectApiName);

            if (sObjectType == null) {
                for (String key : globalDescribe.keySet()) {
                    if (key.equalsIgnoreCase(objectApiName)) {
                        sObjectType = globalDescribe.get(key);
                        break;
                    }
                }
            }

            if (sObjectType == null) {
                throw new PicklistServiceException('Object not found: ' + objectApiName);
            }

            // 2. Resolve Field API Name (Case-Insensitive)
            DescribeSObjectResult sObjectDescribe = sObjectType.getDescribe();
            Map<String, SObjectField> fieldsMap = sObjectDescribe.fields.getMap();
            SObjectField sObjectField = fieldsMap.get(fieldApiName);

            if (sObjectField == null) {
                for (String key : fieldsMap.keySet()) {
                    if (key.equalsIgnoreCase(fieldApiName)) {
                        sObjectField = fieldsMap.get(key);
                        break;
                    }
                }
            }

            if (sObjectField == null) {
                throw new PicklistServiceException('Field not found: ' + fieldApiName);
            }

            // 3. Validate Field Type
            DescribeFieldResult fieldDescribe = sObjectField.getDescribe();
            if (fieldDescribe.getType() != Schema.DisplayType.Picklist) {
                throw new PicklistServiceException('Field is not a picklist or multi-select picklist: ' + fieldApiName);
            }

            // 4. Collect Active Options
            List<Schema.PicklistEntry> entries = fieldDescribe.getPicklistValues();
            List<Option> options = new List<Option>();

            for (Schema.PicklistEntry entry : entries) {
                if (entry.isActive()) {
                    options.add(new Option(
                        entry.getValue(), 
                        entry.getLabel(), 
                        entry.isDefaultValue()
                    ));
                }
            }

            return options;

        } catch (PicklistServiceException e) {
            // Re-throw our custom exception
            throw e;
        } catch (Exception e) {
            // Wrap any unexpected exceptions (e.g. internal Schema errors) into our custom exception
            throw new PicklistServiceException('An error occurred while retrieving picklist options: ' + e.getMessage());
        }
    }
}
