    public void execute(QueueableContext context) {
        // Attach finalizer to handle logging and retries regardless of outcome
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            accountsToUpdate.add(new Account(
                Id = accId,
                Description = 'Synced to ERP'
            ));
        }

        // Perform all-or-nothing update. If any record fails, a DML exception is thrown,
        // the transaction is rolled back, and the finalizer is triggered.
        update accountsToUpdate;
    }
