public with sharing class OpportunityPipelineHandler {

    public static void handleAfterInsert(List<Opportunity> newList) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newList) {
            if (opp.AccountId != null && !opp.IsClosed) {
                accountIds.add(opp.AccountId);
            }
        }
        updateAccountPipeline(accountIds);
    }

    public static void handleAfterUpdate(List<Opportunity> newList, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newList) {
            Opportunity oldOpp = oldMap.get(opp.Id);
            // Recalculate if account changed, status changed, or amount changed
            if (opp.AccountId != oldOpp.AccountId || 
                opp.IsClosed != oldOpp.IsClosed || 
                opp.Amount != oldOpp.Amount) {

                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
                if (oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
            }
        }
        updateAccountPipeline(accountIds);
    }

    public static void handleAfterDelete(List<Opportunity> oldList) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : oldList) {
            if (opp.AccountId != null && !opp.IsClosed) {
                accountIds.add(opp.AccountId);
            }
        }
        updateAccountPipeline(accountIds);
    }

    public static void handleAfterUndelete(List<Opportunity> newList) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newList) {
            if (opp.AccountId != null && !opp.IsClosed) {
                accountIds.add(opp.AccountId);
            }
        }
        updateAccountPipeline(accountIds);
    }

    private static void updateAccountPipeline(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Initialize all affected accounts to 0 to handle cases where 
        // the last open opportunity is removed or moved.
        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Id accId : accountIds) {
            accountsToUpdate.put(accId, new Account(
                Id = accId, 
                FB_Open_Pipeline__c = 0, 
                FB_Open_Opportunities__c = 0
            ));
        }

        // Use AggregateQuery to get totals for open opportunities.
        // SUM() ignores nulls; we treat them as 0.
        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) sumAmount, COUNT(Id) countOpps
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id)ar.get('AccountId');
            Decimal sumAmount = (Decimal)ar.get('sumAmount');
            Integer countOpps = (Integer)ar.get('countOpps');

            Account acc = accountsToUpdate.get(accId);
            if (acc != null) {
                acc.FB_Open_Pipeline__c = sumAmount == null ? 0 : sumAmount;
                acc.FB_Open_Opportunities__c = countOpps;
            }
        }

        update accountsToUpdate.values();
    }
}
