/**
 * LogPurgeJob handles the periodic purging of FB_Integration_Log__c records
 * to prevent storage overflow. It implements Schedulable to allow scheduling
 * and Batchable to ensure the purge is bulk-safe and handles high volumes of logs.
 */
public class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {

    /**
     * No-argument constructor as required.
     */
    public LogPurgeJob() {
    }

    /**
     * Schedulable execute method.
     * Triggers the batch process to handle the deletion in chunks.
     */
    public void execute(SchedulableContext sc) {
        Database.executeBatch(this);
    }

    /**
     * Batchable start method.
     * Queries records based on the retention policy:
     * - Non-ERROR logs: deleted after 30 days.
     * - ERROR logs: deleted after 180 days.
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        DateTime thirtyDaysAgo = System.now().addDays(-30);
        DateTime oneEightyDaysAgo = System.now().addDays(-180);

        // In SOQL, != excludes null values. We must explicitly check for null
        // to include blank Level__c records in the 30-day purge rule.
        return Database.getQueryLocator([
            SELECT Id 
            FROM FB_Integration_Log__c 
            WHERE ( (Level__c != 'ERROR' OR Level__c = null) AND CreatedDate < :thirtyDaysAgo )
               OR ( Level__c = 'ERROR' AND CreatedDate < :oneEightyDaysAgo )
        ]);
    }

    /**
     * Batchable execute method.
     * Deletes the current batch of records.
     */
    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        if (!scope.isEmpty()) {
            delete scope;
        }
    }

    /**
     * Batchable finish method.
     */
    public void finish(Database.BatchableContext bc) {
        // No post-processing required.
    }

    /**
     * Schedules the job to run every day at 02:00.
     * @return The Job ID of the scheduled job.
     */
    public static Id scheduleNightly() {
        // Cron expression: seconds, minutes, hours, day-of-month, month, day-of-week
        String cronExp = '0 0 2 * * ?';
        String jobName = 'Log purge (nightly)';
        return System.schedule(jobName, cronExp, new LogPurgeJob());
    }
}
