public with sharing class OpportunityRollupService {
    /**
     * Calculates the sum of won opportunity amounts for the current calendar year for the provided accounts.
     * 
     * @param accountIds A set of Account IDs to calculate revenue for.
     * @return A map where keys are the requested account IDs and values are the total won amount for this year.
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<Id, Decimal>();
        }

        // Initialize the result map with 0 for every requested account ID
        Map<Id, Decimal> results = new Map<Id, Decimal>();
        for (Id accId : accountIds) {
            results.put(accId, 0);
        }

        // Perform a single aggregate query to sum the Amount of won opportunities closed this calendar year
        // THIS_YEAR is a SOQL date literal covering the current calendar year
        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) total 
            FROM Opportunity 
            WHERE AccountId IN :accountIds 
            AND IsWon = true 
            AND CloseDate = THIS_YEAR 
            GROUP BY AccountId
        ]) {
            Id accId = (Id)ar.get('AccountId');
            Decimal sum = (Decimal)ar.get('total');

            // Ensure we don't put a null value in the map if Amount was blank
            results.put(accId, sum != null ? sum : 0);
        }

        return results;
    }
}
