Content-Type: application/json

{
  "allOrNone": false,
  "compositeRequest": [
    {
      "method": "PATCH",
      "url": "/services/data/v61.0/sobjects/Account/Customer_Number__c/C-1001",
      "referenceId": "acct_1001",
      "body": {
        "Name": "Alder Creek Cafe"
      }
