public with sharing class OpportunityWinService {
    /**
     * Marks the specified opportunities as 'Closed Won' and publishes a Deal_Won__e event for each.
     * 
     * @param opportunityIds Set of opportunity IDs to be closed.
     * @return The number of opportunities that were transitioned to 'Closed Won'.
     * @throws Exception propagates DML exceptions from the unit of work commit.
     */
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Load opportunities using the selector
        List<Opportunity> opps = OpportunitiesSelector.newInstance().selectById(opportunityIds);

        fflib_Application.UnitOfWork uow = Application.UnitOfWork.newInstance();
        Integer closedCount = 0;

        for (Opportunity opp : opps) {
            // Skip those already at 'Closed Won'
            if (opp.StageName != 'Closed Won') {
                // Update Opportunity fields
                opp.StageName = 'Closed Won';
                opp.CloseDate = Date.today();
                uow.registerSObject(opp, fflib_SObjectUnitOfWork.UOWAction.update);

                // Create and register Platform Event
                Deal_Won__e event = new Deal_Won__e(
                    Opportunity_Id__c = opp.Id,
                    Amount__c = opp.Amount
                );
                uow.registerSObject(event, fflib_SObjectUnitOfWork.UOWAction.insert);

                closedCount++;
            }
        }

        // Commit all changes (Updates and Event publishing) in one transaction
        if (closedCount > 0) {
            uow.commitWork();
        }

        return closedCount;
    }
}
