public with sharing class ContactPhoneCleanup {
    /**
     * Normalizes phone numbers for a list of Contacts by removing all characters 
     * except digits and the plus sign.
     * 
     * @param contactIds List of Contact IDs to process.
     * @return A map of Contact IDs that failed to save and their first error message.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        if (contactIds == null || contactIds.isEmpty()) {
            return new Map<Id, String>();
        }

        Map<Id, String> errorMap = new Map<Id, String>();
        List<Contact> contactsToUpdate = new List<Contact>();

        // Query only the necessary fields for the provided IDs
        for (Contact con : [SELECT Id, Phone FROM Contact WHERE Id IN :contactIds]) {
            // Contacts without a phone are left out
            if (String.isBlank(con.Phone)) {
                continue;
            }

            String originalPhone = con.Phone;
            // Remove every character that is not a digit or +
            String cleanedPhone = originalPhone.replaceAll('[^0-9+]', '');

            // Only stage for update if the value actually changed to optimize performance
            if (originalPhone != cleanedPhone) {
                con.Phone = cleanedPhone;
                contactsToUpdate.add(con);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            // Perform partial success update
            Database.SaveResult[] results = Database.update(contactsToUpdate, false);

            // Process results to identify failures
            for (Database.SaveResult result : results) {
                if (!result.isSuccess()) {
                    // Map the Id of the failed record to its first error message
                    if (result.getErrors().size() > 0) {
                        errorMap.put(result.getId(), result.getErrors()[0].getMessage());
                    }
                }
            }
        }

        return errorMap;
    }
}
