    /**
     * Sets Case Priority to 'High' if the associated Account rating is 'Hot'.
     * Bulkified to handle ERP integrations sending up to 200 records per transaction.
     */
    public static void handleBeforeInsert(List<Case> newCases) {
        Set<Id> accountIds = new Set<Id>();

        // Collect all Account IDs to avoid querying inside the loop
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // Fetch only the accounts that meet the 'Hot' criteria
        Map<Id, Account> hotAccounts = new Map<Id, Account>([
            SELECT Id 
            FROM Account 
            WHERE Id IN :accountIds AND Rating = 'Hot'
        ]);

        // Apply the priority logic based on the map of Hot accounts
        for (Case c : newCases) {
            if (c.AccountId != null && hotAccounts.containsKey(c.AccountId)) {
                c.Priority = 'High';
            }
        }
    }
}
