public with sharing class FollowUpTaskService {
    /**
     * Creates follow-up tasks for the provided Opportunity IDs.
     * Returns a set of Opportunity IDs for which the task could not be created.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return new Set<Id>();
        }

        Set<Id> failedOppIds = new Set<Id>();

        // Fetch necessary Opportunity data to populate Task fields
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Name, OwnerId FROM Opportunity WHERE Id IN :opportunityIds]
        );

        List<Task> tasksToCreate = new List<Task>();
        List<Id> taskToOppIdOrder = new List<Id>();

        for (Id oppId : opportunityIds) {
            Opportunity opp = oppMap.get(oppId);

            // If the Opportunity doesn't exist or couldn't be queried, mark as failed
            if (opp == null) {
                failedOppIds.add(oppId);
                continue;
            }

            tasksToCreate.add(new Task(
                WhatId = opp.Id,
                OwnerId = opp.OwnerId,
                Subject = 'Follow up: ' + opp.Name,
                ActivityDate = Date.today().addDays(7),
                Status = 'Not Started',
                Priority = 'Normal'
            ));

            // Keep track of the Opportunity ID associated with the task at this index
            taskToOppIdOrder.add(oppId);
        }

        if (!tasksToCreate.isEmpty()) {
            // Use allOrNone = false to allow partial success (ignores validation rule failures for specific records)
            Database.SaveResult[] results = Database.insert(tasksToCreate, false);

            for (Integer i = 0; i < results.size(); i++) {
                if (!results[i].isSuccess()) {
                    // Map the failed result back to the original Opportunity ID
                    failedOppIds.add(taskToOppIdOrder[i]);
                }
            }
        }

        return failedOppIds;
    }
}
