public class CaseSurveyJob implements Queueable {
    private List<Id> caseIds;

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public void execute(QueueableContext context) {
        // Query necessary fields for the identified cases
        List<Case> cases = [SELECT Id, CaseNumber, ContactId FROM Case WHERE Id IN :caseIds];
        List<Task> tasksToInsert = new List<Task>();

        for (Case c : cases) {
            tasksToInsert.add(new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status = 'Not Started'
            ));
        }

        if (!tasksToInsert.isEmpty()) {
            // allOrNone = false ensures that if one task fails to insert, 
            // the others are still processed, fulfilling the isolation requirement.
            Database.insert(tasksToInsert, false);
        }
    }
}
