        return count === 1 ? '1 contact' : `${count} contacts`;
    }

    /**
     * Returns a sorted copy of the contacts array to avoid mutating the @api property.
     * Sorting is performed by Name in ascending order.
     */
    get sortedContacts() {
        if (!this.hasContacts) {
            return [];
        }
        return [...this.contacts].sort((a, b) => {
            const nameA = a.Name || '';
            const nameB = b.Name || '';
            return nameA.localeCompare(nameB);
        });
    }
