import { LightningElement, wire } from 'lwc';
import { 
    publish, 
    subscribe, 
    unsubscribe, 
    MessageContext, 
    APPLICATION_SCOPE 
} from 'lightning/messageService';
import ACCOUNT_SELECTED_CHANNEL from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    selectedAccountId;
    subscription = null;

    @wire(MessageContext)
    messageContext;

    connectedCallback() {
        this.subscribeToChannel();
    }

    disconnectedCallback() {
        this.unsubscribeFromChannel();
    }

    subscribeToChannel() {
        // Ensure only one subscription is held
        if (!this.subscription) {
            this.subscription = subscribe(
                this.messageContext,
                ACCOUNT_SELECTED_CHANNEL,
                (message) => this.handleMessage(message),
                { 
                    scope: APPLICATION_SCOPE 
                }
            );
        }
    }

    unsubscribeFromChannel() {
        if (this.subscription) {
            unsubscribe(this.subscription);
            this.subscription = null;
        }
    }

    handleMessage(message) {
        // Update the account Id to trigger the view form or placeholder
        this.selectedAccountId = message.recordId;
    }

    handleAction(event) {
        const action = event.target.dataset.action;
        if (action === 'clear') {
            // Publish a null recordId to clear selection across all listeners
            publish(this.messageContext, ACCOUNT_SELECTED_CHANNEL, { recordId: null });
        }
    }
}
