import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { deleteRecord } from 'lightning/uiRecordApi';
import LightningConfirm from 'lightning/confirm';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    _opportunities = [];

    @api
    set opportunities(value) {
        // Create a shallow copy to allow local removal of rows without mutating the parent's array
        this._opportunities = value ? [...value] : [];
    }

    get opportunities() {
        return this._opportunities;
    }

    columns = [
        { label: 'Name', fieldName: 'Name' },
        { label: 'Stage', fieldName: 'StageName' },
        { label: 'Amount', fieldName: 'Amount', type: 'currency' },
        {
            type: 'action',
            typeAttributes: {
                rowActions: [
                    { label: 'View', name: 'view' },
                    { label: 'Edit', name: 'edit' },
                    { label: 'Delete', name: 'delete' },
                ],
            },
        },
    ];

    async handleRowAction(event) {
        const actionName = event.detail.action.name;
        const row = event.detail.row;

        switch (actionName) {
            case 'view':
                this.navigateToRecord(row.Id, 'view');
                break;
            case 'edit':
                this.navigateToRecord(row.Id, 'edit');
                break;
            case 'delete':
                await this.handleDelete(row);
                break;
            default:
                break;
        }
    }

    navigateToRecord(recordId, action) {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId: recordId,
                actionName: action,
            },
        });
    }

    async handleDelete(row) {
        const confirmed = await LightningConfirm.open({
            message: `Are you sure you want to delete the opportunity ${row.Name}?`,
            variant: 'headerless',
            label: 'Confirm Delete',
        });

        if (confirmed) {
            try {
                await deleteRecord(row.Id);

                // Remove the row from the local copy
                this._opportunities = this._opportunities.filter(opp => opp.Id !== row.Id);

                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Opportunity deleted',
                        variant: 'success',
                    })
                );
            } catch (error) {
                const errorMessage = error.body ? error.body.message : 'Unknown error occurred';
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Delete failed',
                        message: errorMessage,
                        variant: 'error',
                    })
                );
            }
        }
    }
}
