export default class OrderLinesPanel extends LightningElement {
    /** @type {Array<{ key: string, productName: string, quantity: number }>} */
    @api lines = [];
    showError = false;

    handleAction(event) {
        const action = event.target.dataset.action;
        if (action === 'reset') {
            this.handleReset();
        } else if (action === 'submit') {
            this.handleSubmit();
        }
    }

    handleReset() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        editors.forEach(editor => editor.reset());
    }

    handleSubmit() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        let allValid = true;

        // Validate every editor, regardless of whether one fails
        editors.forEach(editor => {
            if (!editor.validate()) {
                allValid = false;
            }
        });

        if (allValid) {
            // Collect values in display order
            const values = Array.from(editors).map(editor => editor.getValue());

            this.dispatchEvent(new CustomEvent('submit', {
                detail: { lines: values }
            }));

            this.showError = false;
        } else {
            this.showError = true;
        }
    }
}
