import { LightningElement, track } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    @track waiting;
    @track longestWaitMinutes;
    @track error;

    intervalId;
    isLoading = false;
    hasLoaded = false;

    REFRESH_INTERVAL = 60000;

    connectedCallback() {
        // Initial load
        this.fetchStats();

        // Set up polling
        this.intervalId = setInterval(() => {
            this.fetchStats();
        }, this.REFRESH_INTERVAL);

        // Listen for visibility changes
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
    }

    disconnectedCallback() {
        // Stop polling and clean up listeners
        if (this.intervalId) {
            clearInterval(this.intervalId);
        }
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            this.fetchStats();
        }
    };

    async fetchStats() {
        // Do not start a request while the previous one is in flight
        // Do not make requests while the tab is hidden
        if (this.isLoading || document.visibilityState === 'hidden') {
            return;
        }

        this.isLoading = true;

        try {
            const result = await getQueueStats();
            this.waiting = result.waiting;
            this.longestWaitMinutes = result.longestWaitMinutes;
            this.error = null;
            this.hasLoaded = true;
        } catch (err) {
            // Extract error message from the Salesforce error structure
            this.error = err?.body?.message || err?.message || 'Unknown error occurred';
        } finally {
            this.isLoading = false;
        }
    }
}
