import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleInputChange(event) {
        const field = event.target.dataset.field;
        this[field] = event.detail.value;
    }

    async handleRegister() {
        const emailInput = this.template.querySelector('[data-field="email"]');
        const forbiddenDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

        // 1. Validate email domain (case-insensitive)
        const emailValue = this.email.toLowerCase();
        const isForbidden = forbiddenDomains.some(domain => emailValue.endsWith(`@${domain}`));

        if (isForbidden) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // 2. Call reportValidity() on every input
        const inputs = this.template.querySelectorAll('lightning-input');
        let allValid = true;
        inputs.forEach(input => {
            if (!input.reportValidity()) {
                allValid = false;
            }
        });

        // 3. If any input is invalid, stop
        if (!allValid) {
            return;
        }

        // 4. Call register imperatively
        try {
            await register({ 
                fullName: this.fullName, 
                email: this.email, 
                company: this.company 
            });

            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'success',
                    title: 'Registered'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'error',
                    title: 'Registration failed',
                    message: error.body?.message || 'An unknown error occurred'
                })
            );
        }
    }
}
