import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    _value;
    _options = [];

    @api label;

    @api 
    get options() {
        return this._options;
    }

    set options(value) {
        this._options = value || [];
        this.syncActiveIndex();
    }

    @api 
    get value() {
        return this._value;
    }

    set value(val) {
        this._value = val;
        this.syncActiveIndex();
    }

    activeIndex = 0;

    /**
     * Ensures activeIndex points to the currently selected value, 
     * or defaults to the first option.
     */
    syncActiveIndex() {
        if (!this._options || this._options.length === 0) {
            this.activeIndex = 0;
            return;
        }

        const index = this._options.findIndex(opt => opt.value === this._value);
        this.activeIndex = index !== -1 ? index : 0;
    }

    /**
     * Computed list for the template to handle ARIA attributes and unique IDs
     */
    get listOptions() {
        return this._options.map((opt, index) => ({
            ...opt,
            id: `option-${index}`,
            index: index,
            isSelected: opt.value === this._value
        }));
    }

    get activeId() {
        return `option-${this.activeIndex}`;
    }

    handleKeyDown(event) {
        const { key } = event;
        let handled = false;

        switch (key) {
            case 'ArrowDown':
                if (this.activeIndex < this._options.length - 1) {
                    this.activeIndex++;
                    handled = true;
                }
                break;
            case 'ArrowUp':
                if (this.activeIndex > 0) {
                    this.activeIndex--;
                    handled = true;
                }
                break;
            case 'Home':
                this.activeIndex = 0;
                handled = true;
                break;
            case 'End':
                this.activeIndex = this._options.length - 1;
                handled = true;
                break;
            case 'Enter':
            case ' ':
                this.selectActive();
                handled = true;
                break;
        }

        if (handled) {
            event.preventDefault();
        }
    }

    handleOptionClick(event) {
        const index = parseInt(event.currentTarget.dataset.index, 10);
        this.activeIndex = index;
        this.selectOptionByIndex(index);
    }

    selectActive() {
        this.selectOptionByIndex(this.activeIndex);
    }

    selectOptionByIndex(index) {
        if (!this._options[index]) return;

        const newValue = this._options[index].value;
        if (newValue !== this._value) {
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: newValue }
            }));
        }
    }
}
