import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this.items;
    }

    set tasks(value) {
        // Work on a copy to avoid mutating parent's data
        this.items = value ? value.map((task) => ({ ...task })) : [];
    }

    get formattedHeading() {
        return (this.heading || '').toUpperCase();
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = this.newLabel ? this.newLabel.trim() : '';
        if (!label) {
            return;
        }

        const newTask = {
            id: `new-${this.nextId++}`,
            label: label,
            done: false
        };

        // Update array reference to ensure reactivity
        this.items = [...this.items, newTask];
        this.newLabel = '';

        this.dispatchEvent(new CustomEvent('taskadded', {
            detail: { label }
        }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        // Create a new array and new object reference to trigger reactivity
        this.items = this.items.map((task) => {
            if (task.id === id) {
                return { ...task, done: !task.done };
            }
            return task;
        });
    }
}
