public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    /**
     * Records monthly giving sign-ups as NPSP Enhanced Recurring Donations.
     * 
     * @param requests List of gift requests to process.
     * @return List of created npe03__Recurring_Donation__c Ids in the original order.
     * @throws RecurringGiftException if any request contains invalid data.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // Validation: Check all requests before any DML operation
        for (GiftRequest req : requests) {
            if (req.contactId == null || 
                req.amount == null || req.amount <= 0 || 
                req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31 || 
                req.startDate == null) {
                throw new RecurringGiftException('Invalid gift request: Contact, positive amount, day of month (1-31), and start date are required.');
            }
        }

        List<npe03__Recurring_Donation__c> recurringDonations = new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {
            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();

            // Donor and Financials
            rd.npe03__Contact__c = req.contactId;
            rd.npe03__Amount__c = req.amount;

            // Frequency and Schedule
            rd.npe03__Installment_Period__c = 'Monthly';
            rd.npsp__InstallmentFrequency__c = 'Monthly';
            rd.npsp__StartDate__c = req.startDate;
            rd.npsp__Status__c = 'Active';
            rd.npsp__PaymentMethod__c = req.paymentMethod;

            // Handle Day of Month logic (31 = Last Day)
            if (req.dayOfMonth == 31) {
                rd.npsp__Always_Use_Last_Day_Of_Month__c = true;
                rd.npsp__Day_of_Month__c = null;
            } else {
                rd.npsp__Always_Use_Last_Day_Of_Month__c = false;
                rd.npsp__Day_of_Month__c = req.dayOfMonth;
            }

            // Handle Open-Ended vs Fixed installments
            if (req.installments == null || req.installments <= 0) {
                rd.npe03__Open_Ended_Status__c = 'Open Ended';
                rd.npe03__Installments__c = null;
            } else {
                rd.npe03__Open_Ended_Status__c = 'Fixed';
                rd.npe03__Installments__c = req.installments;
            }

            recurringDonations.add(rd);
        }

        // Single DML statement for bulk safety
        insert recurringDonations;

        // Return IDs in the order of the original requests
        List<Id> resultIds = new List<Id>();
        for (npe03__Recurring_Donation__c rd : recurringDonations) {
            resultIds.add(rd.Id);
        }

        return resultIds;
    }
}
