public with sharing class GauAllocationService {

    /**
     * Custom exception for GAU allocation validation errors.
     */
    public class AllocationException extends Exception {}

    /**
     * Replaces existing GAU allocations for an opportunity with new allocations 
     * based on provided percentages.
     * 
     * @param opportunityId The Id of the Opportunity to allocate.
     * @param percentByGauId A map where keys are GAU Ids and values are percentages (e.g., 60 for 60%).
     * @return The list of inserted npsp__Allocation__c records.
     * @throws AllocationException if validation fails.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // 1. Basic map validation
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('The GAU allocation map cannot be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);

            // Percentage must be present and > 0
            if (pct == null || pct <= 0) {
                throw new AllocationException('Each allocation percentage must be greater than 0.');
            }
            totalPercent += pct;
        }

        // Total cannot exceed 100%
        if (totalPercent > 100) {
            throw new AllocationException('Total allocation percentage cannot exceed 100%.');
        }

        // 2. GAU Status Validation
        Set<Id> gauIds = percentByGauId.keySet();
        Map<Id, npsp__General_Accounting_Unit__c> gauMap = new Map<Id, npsp__General_Accounting_Unit__c>([
            SELECT Id, npsp__Active__c 
            FROM npsp__General_Accounting_Unit__c 
            WHERE Id IN :gauIds
        ]);

        // Ensure all requested GAUs exist in the database
        if (gauMap.size() != gauIds.size()) {
            throw new AllocationException('One or more provided GAU IDs are invalid.');
        }

        // Ensure all requested GAUs are active
        for (npsp__General_Accounting_Unit__c gau : gauMap.values()) {
            if (!gau.npsp__Active__c) {
                throw new AllocationException('One or more provided GAUs are inactive.');
            }
        }

        // 3. Data Manipulation
        // We perform all validations first to ensure "Validate everything before changing any data"

        // Replace existing allocations
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id 
            FROM npsp__Allocation__c 
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        // Create new allocations. 
        // By setting npsp__Percent__c, NPSP automatically handles the calculation of 
        // npsp__Amount__c and updates it if the Opportunity Amount changes in the future.
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            newAllocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        insert newAllocations;

        return newAllocations;
    }
}
