public with sharing class HouseholdService {

    /**
     * Creates a single NPSP Household Account and associates the provided contacts to it.
     * The first contact in the list is established as the primary contact by NPSP 
     * based on the association order.
     * 
     * @param members List of new Contact records to be added to the household.
     * @return The Id of the created Household Account.
     * @throws IllegalArgumentException if the members list is null or empty.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('The members list cannot be null or empty.');
        }

        // Fetch the Household Account record type Id dynamically to avoid hard-coding.
        Id householdRecordTypeId = SObjectType.Account.getRecordTypeInfosByName()
            .get('Household Account')
            .getId();

        // Create the Household Account. 
        // We provide a placeholder name because Account.Name is a required field.
        // NPSP's trigger logic will automatically rename the account based on 
        // the primary contact once the contacts are inserted and linked.
        Account householdAccount = new Account(
            RecordTypeId = householdRecordTypeId,
            Name = 'Household' 
        );

        insert householdAccount;

        // Associate all provided contacts with the new household account.
        // Since the contacts are inserted as a list linked to the same account,
        // NPSP identifies the first one created/linked as the primary contact.
        for (Contact member : members) {
            member.AccountId = householdAccount.Id;
        }

        insert members;

        return householdAccount.Id;
    }
}
