public with sharing class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    /**
     * Schedules monthly installments for a given Opportunity (Pledge).
     * 
     * @param opportunityId The Id of the Opportunity to schedule payments for.
     * @param numberOfPayments The number of installments to create.
     * @param firstPaymentDate The date of the first installment.
     * @return The list of newly created payments in schedule order.
     * @throws PaymentPlanException if validations fail.
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(Id opportunityId, Integer numberOfPayments, Date firstPaymentDate) {
        // 1. Basic input validation
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('Number of payments must be 1 or greater.');
        }

        // 2. Opportunity validation
        Opportunity opp = [
            SELECT Amount, IsClosed 
            FROM Opportunity 
            WHERE Id = :opportunityId 
            LIMIT 1
        ];

        if (opp.IsClosed) {
            throw new PaymentPlanException('The opportunity is closed and cannot be scheduled for payments.');
        }

        // 3. Payment Analysis
        List<npe01__OppPayment__c> allPayments = [
            SELECT npe01__Payment_Amount__c, npe01__Payment_Status__c 
            FROM npe01__OppPayment__c 
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        Decimal totalPledgeAmount = opp.Amount != null ? opp.Amount : 0;
        Decimal amountPaidOrWrittenOff = 0;
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c p : allPayments) {
            if ('Paid'.equals(p.npe01__Payment_Status__c) || 'Written Off'.equals(p.npe01__Payment_Status__c)) {
                amountPaidOrWrittenOff += (p.npe01__Payment_Amount__c != null) ? p.npe01__Payment_Amount__c : 0;
            } else {
                // Payments that are neither Paid nor Written Off are considered "unpaid" and should be replaced
                paymentsToDelete.add(p);
            }
        }

        Decimal outstandingAmount = totalPledgeAmount - amountPaidOrWrittenOff;

        if (outstandingAmount <= 0) {
            throw new PaymentPlanException('The outstanding amount must be greater than zero to create a payment plan.');
        }

        // 4. Calculate Installments
        // Divide outstanding amount by number of payments, rounded down to the cent
        Decimal installmentAmount = (outstandingAmount / numberOfPayments).setScale(2, System.RoundingMode.DOWN);
        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        Decimal totalScheduled = 0;

        for (Integer i = 0; i < numberOfPayments; i++) {
            npe01__OppPayment__c p = new npe01__OppPayment__c();
            p.npe01__Opportunity__c = opportunityId;
            p.npe01__Payment_Date__c = firstPaymentDate.addMonths(i);
            p.npe01__Payment_Status__c = 'Unpaid';

            if (i < numberOfPayments - 1) {
                p.npe01__Payment_Amount__c = installmentAmount;
                totalScheduled += installmentAmount;
            } else {
                // Last payment absorbs the remainder to ensure the total matches the outstanding amount exactly
                p.npe01__Payment_Amount__c = outstandingAmount - totalScheduled;
            }
            newPayments.add(p);
        }

        // 5. Persistence
        if (!paymentsToDelete.isEmpty()) {
            delete paymentsToDelete;
        }
        insert newPayments;

        return newPayments;
    }
}
