/**
 * Service class to manage Family Relationships in NPSP.
 */
public with sharing class FamilyService {

    /**
     * Links parents to children in NPSP.
     * 
     * For each child-parent pair, a relationship is created where the parent is the child's 'Parent'.
     * NPSP's "List Setting" reciprocal method automatically creates the reciprocal 
     * relationship (Son, Daughter, or Child) based on the contact's gender.
     *
     * @param parentIdByChildId Map where keys are child Contact Ids and values are parent Contact Ids.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect all involved contact IDs to perform a single bulk query
        Set<Id> allContactIds = new Set<Id>();
        allContactIds.addAll(parentIdByChildId.keySet());
        allContactIds.addAll(parentIdByChildId.values());

        // Identify existing relationships between any of the provided contacts
        // to ensure the process is idempotent (safe to re-run).
        // We only care about relationships where both parties are in our current set.
        Set<String> existingPairs = new Set<String>();
        for (npsp__Relationship__c rel : [
            SELECT npsp__Contact__c, npsp__Related_Contact__c 
            FROM npsp__Relationship__c 
            WHERE npsp__Contact__c IN :allContactIds 
            AND npsp__Related_Contact__c IN :allContactIds
        ]) {
            existingPairs.add(rel.npsp__Contact__c + '-' + rel.npsp__Related_Contact__c);
        }

        List<npsp__Relationship__c> relationshipsToInsert = new List<npsp__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (parentId == null) continue;

            // Skip if a relationship already exists in either direction
            if (existingPairs.contains(childId + '-' + parentId) || 
                existingPairs.contains(parentId + '-' + childId)) {
                continue;
            }

            // Create the Relationship record: child is the primary contact, parent is the related contact.
            relationshipsToInsert.add(new npsp__Relationship__c(
                npsp__Contact__c = childId,
                npsp__Related_Contact__c = parentId,
                npsp__Relationship_Type__c = 'Parent',
                npsp__Relationship_Status__c = 'Current'
            ));
        }

        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }
}
