/**
 * TDTM Trigger Handler for Opportunity Major Gift Follow-up.
 * Registered for AfterInsert and AfterUpdate on Opportunity.
 */
public with sharing class OPP_MajorGiftFollowUp_TDTM {

    /**
     * TDTM run method called by NPSP's TriggerHandlerDispatcher.
     * 
     * @param newSObjects The list of records being processed.
     * @param oldSObjects The list of records before the changes (null on Insert).
     */
    public void run(List<SObject> newSObjects, List<SObject> oldSObjects) {
        if (newSObjects == null || newSObjects.isEmpty()) {
            return;
        }

        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < newSObjects.size(); i++) {
            Opportunity newOpp = (Opportunity)newSObjects[i];
            Opportunity oldOpp = (oldSObjects != null) ? (Opportunity)oldSObjects[i] : null;

            // Criteria: Closed Won and Amount >= 5000
            Boolean qualifiesNow = (newOpp.StageName == 'Closed Won' && 
                                    newOpp.Amount != null && 
                                    newOpp.Amount >= 5000);

            Boolean qualifiesBefore = false;
            if (oldOpp != null) {
                qualifiesBefore = (oldOpp.StageName == 'Closed Won' && 
                                   oldOpp.Amount != null && 
                                   oldOpp.Amount >= 5000);
            }

            // Only create task if the Opportunity just became qualifying
            if (qualifiesNow && !qualifiesBefore) {
                Task followUpTask = new Task();
                followUpTask.Subject = 'Major gift thank-you call';
                followUpTask.Priority = 'High';
                followUpTask.Status = 'Not Started';
                followUpTask.WhatId = newOpp.Id;
                followUpTask.WhoId = newOpp.npsp__Primary_Contact__c;
                followUpTask.OwnerId = newOpp.OwnerId;

                if (newOpp.CloseDate != null) {
                    followUpTask.ActivityDate = newOpp.CloseDate.addDays(3);
                }

                tasksToInsert.add(followUpTask);
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
