public with sharing class RecordAccessService {
    /**
     * Returns the subset of recordIds that the running user has permission to edit.
     * This method accounts for object permissions, ownership, sharing rules, 
     * role hierarchy, and 'Modify All Data'/'Modify All' permissions via the 
     * UserRecordAccess system object.
     * 
     * @param recordIds A set of record IDs to evaluate. Supports up to 2,000 IDs across multiple objects.
     * @return A set containing only the IDs from the input set that the user can edit. 
     *         Returns an empty set if input is null or empty.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        if (recordIds == null || recordIds.isEmpty()) {
            return new Set<Id>();
        }

        Set<Id> editableIds = new Set<Id>();

        /**
         * UserRecordAccess is a system table that aggregates all sharing and permission logic.
         * Requirements for querying UserRecordAccess:
         * 1. Must filter by UserId and/or RecordId.
         * 2. Use of the IN operator for RecordId is permitted and supports mixed object types.
         * 3. This approach is bulk-safe and uses only one SOQL query for the provided set.
         */
        for (UserRecordAccess ura : [
            SELECT RecordId 
            FROM UserRecordAccess 
            WHERE UserId = :UserInfo.getUserId() 
            AND RecordId IN :recordIds 
            AND HasEditAccess = true
        ]) {
            editableIds.add(ura.RecordId);
        }

        return editableIds;
    }
}
