public with sharing class EmployeeDirectoryService {
    /**
     * Returns FB_Employee__c records the running user has access to via sharing.
     * Respects field-level security by omitting fields the user cannot read.
     * 
     * @return List of FB_Employee__c records ordered by Name ASC.
     */
    public static List<FB_Employee__c> getDirectory() {
        // Check if user has read access to the object
        if (!Schema.SObjectType.FB_Employee__c.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Id and Name are required fields for the return
        List<String> queryFields = new List<String>{'Id', 'Name'};

        // Dynamically add custom fields based on FLS (Field Level Security)
        // By not querying the field, it remains 'absent' from the SObject instance,
        // which ensures that when serialized (e.g., for LWC), it is undefined rather than null.
        if (Schema.SObjectType.FB_Employee__c.fields.Department__c.getDescribe().isAccessible()) {
            queryFields.add('Department__c');
        }
        if (Schema.SObjectType.FB_Employee__c.fields.Salary__c.getDescribe().isAccessible()) {
            queryFields.add('Salary__c');
        }
        if (Schema.SObjectType.FB_Employee__c.fields.Personal_Email__c.getDescribe().isAccessible()) {
            queryFields.add('Personal_Email__c');
        }

        // Construct the dynamic SOQL query
        String query = 'SELECT ' + String.join(queryFields, ', ') + 
                      ' FROM FB_Employee__c ' + 
                      ' ORDER BY Name ASC';

        // 'with sharing' keyword on class ensures record-level sharing is enforced
        return Database.query(query);
    }
}
