/**
 * @description Trigger Action to create an onboarding Task for the Account owner 
 * when an Account of type 'Customer - Direct' or 'Customer - Channel' is created.
 */
public class TA_Account_CreateOnboardingTask implements TriggerAction {

    public void execute(TriggerActionContext context) {
        List<Task> tasksToInsert = new List<Task>();
        Set<String> targetTypes = new Set<String>{'Customer - Direct', 'Customer - Channel'};

        for (SObject record : context.records) {
            Account acc = (Account) record;

            if (targetTypes.contains(acc.Type)) {
                tasksToInsert.add(new Task(
                    Subject = 'Onboard new customer',
                    WhatId = acc.Id,
                    OwnerId = acc.OwnerId,
                    ActivityDate = Date.today().addDays(7),
                    Status = 'Not Started',
                    Priority = 'Normal'
                ));
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
