public with sharing class ContactImportService {
    /**
     * Imports contacts from a legacy system.
     * Bypasses the 'TA_Contact_CreateWelcomeTask' trigger action to prevent 
     * sending welcome packs to existing customers, while allowing other 
     * automation (like phone formatting) to run.
     * 
     * @param contacts List of contacts to be inserted.
     */
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // TAF bypasses are stored in a static set within the TriggerAction class.
        // We enable the bypass for the specific welcome task action.
        TriggerAction.bypass('TA_Contact_CreateWelcomeTask');

        try {
            insert contacts;
        } finally {
            // Ensure that the bypass is cleared regardless of whether the DML succeeded.
            // This ensures that subsequent inserts in the same transaction
            // will correctly trigger the welcome task.
            TriggerAction.clearBypass();
        }
    }
}
