     * @throws DmlException or any other exception propagated from the DML operations.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Enable bypass for Account sObject to prevent expensive TAF actions.
        TriggerActions.setBypass(Account.SObjectType, true);

        try {
            // 1st DML: Update Accounts
            // We instantiate Account records with the ID to avoid an unnecessary SOQL query.
            List<Account> accountsToUpdate = new List<Account>();
            for (Id accId : accountIds) {
                accountsToUpdate.add(new Account(Id = accId, OwnerId = newOwnerId));
            }
            update accountsToUpdate;

            // 1st SOQL: Get all related Contacts.
            List<Contact> contactsToUpdate = [SELECT Id FROM Contact WHERE AccountId IN :accountIds];

            // 2nd DML: Update Contacts.
            // Contact trigger actions are allowed to run as per requirements.
            for (Contact con : contactsToUpdate) {
                con.OwnerId = newOwnerId;
            }
            update contactsToUpdate;

        } finally {
            // Ensure Account automation is restored regardless of success or failure.
            TriggerActions.setBypass(Account.SObjectType, false);
        }
    }
}
