public with sharing class TA_Opportunity_CollectForErpSync implements TriggerAction {
    public void execute(TriggerActionContext context) {
        for (SObject record : context.records) {
            Opportunity opp = (Opportunity) record;

            if (context.oldMap == null) {
                // After Insert: all records are collected
                OpportunityErpSyncFinalizer.addId(opp.Id);
            } else {
                // After Update: only collect if StageName has changed
                Opportunity oldOpp = (Opportunity) context.oldMap.get(opp.Id);
                if (oldOpp.StageName != opp.StageName) {
                    OpportunityErpSyncFinalizer.addId(opp.Id);
                }
            }
        }
    }
}
