/**
 * TAF Trigger Action to prevent duplicate emails per Account.
 * Rule: Two Contacts of the same Account may not share an email address (case-insensitively).
 */
public class TA_Contact_PreventDuplicateEmail implements TriggerAction {

    public void execute(List<SObject> records, Map<Id, SObject> oldMap) {
        List<Contact> contacts = (List<Contact>) records;
        Map<Id, Contact> oldContactMap = (Map<Id, Contact>) oldMap;

        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        Set<String> seenInBatch = new Set<String>();
        Set<Contact> candidates = new Set<Contact>();

        // Step 1: Filter records and handle intra-batch duplicates
        for (Contact c : contacts) {
            // Rule: Contacts without an Account or without an Email are not checked
            if (c.AccountId == null || c.Email == null) {
                continue;
            }

            // Rule: On update, only contacts whose Email or AccountId changed are checked
            if (oldContactMap != null) {
                Contact oldContact = oldContactMap.get(c.Id);
                if (c.Email == oldContact.Email && c.AccountId == oldContact.AccountId) {
                    continue;
                }
            }

            String key = (c.AccountId + '|' + c.Email).toLowerCase();

            // Rule: Within a single save, the first one in the list is accepted and each later one is rejected
            if (seenInBatch.contains(key)) {
                c.addError('Another contact on this account already uses this email address.');
            } else {
                seenInBatch.add(key);
                candidates.add(c);
                accountIds.add(c.AccountId);
                emails.add(c.Email);
            }
        }

        if (candidates.isEmpty()) {
            return;
        }

        // Step 2: Bulk-safe DB check (one SOQL query)
        // SOQL is case-insensitive for the Email field.
        Map<String, Id> existingEmailsMap = new Map<String, Id>();
        for (Contact existing : [
            SELECT Id, AccountId, Email 
            FROM Contact 
            WHERE AccountId IN :accountIds 
            AND Email IN :emails
        ]) {
            String key = (existing.AccountId + '|' + existing.Email).toLowerCase();
            existingEmailsMap.put(key, existing.Id);
        }

        // Step 3: Validate candidates against DB results
        for (Contact c : candidates) {
            String key = (c.AccountId + '|' + c.Email).toLowerCase();
            if (existingEmailsMap.containsKey(key)) {
                Id existingId = existingEmailsMap.get(key);
                // Rule: A contact never conflicts with itself
                if (c.Id == null || existingId != c.Id) {
                    c.addError('Another contact on this account already uses this email address.');
                }
            }
        }
    }
}
