/**
 * Trigger Action to normalize Lead contact information on creation.
 * Implements the Trigger Action Framework (TAF) interface.
 */
public class TA_Lead_NormalizeContactInfo implements TriggerAction {

    public void execute(List<SObject> records) {
        for (SObject record : records) {
            Lead lead = (Lead)record;

            // Email: leading/trailing whitespace removed and lower-cased
            if (lead.Email != null) {
                lead.Email = lead.Email.trim().toLowerCase();
            }

            // Company: leading/trailing whitespace removed
            if (lead.Company != null) {
                lead.Company = lead.Company.trim();
            }

            // LeadSource: set to 'Web' when blank; an existing value is kept
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }
        }
    }
}
