public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    /**
     * Static set to ensure only one audit task is created per Opportunity per transaction,
     * preventing duplicate tasks when subsequent actions (like rounding) update the record again.
     */
    private static Set<Id> processedOppIds = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        List<Task> tasksToInsert = new List<Task>();

        // triggerNew and triggerOld are aligned by index in the Salesforce trigger context
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity oppNew = triggerNew[i];
            Opportunity oppOld = triggerOld[i];

            // Detect change in Amount and ensure we haven't already logged this Opportunity in the current transaction
            if (oppNew.Amount != oppOld.Amount && !processedOppIds.contains(oppNew.Id)) {
                tasksToInsert.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = oppNew.Id,
                    Status = 'Completed'
                ));

                // Mark as processed for this transaction
                processedOppIds.add(oppNew.Id);
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
