/**
 * Singleton class to manage Account data shared across multiple Contact trigger actions
 * to prevent redundant SOQL queries within a single trigger execution context.
 */
public class TA_Contact_Queries {
    private static TA_Contact_Queries instance;
    public Map<Id, Account> accountsById = new Map<Id, Account>();

    private TA_Contact_Queries() {}

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger action that populates the singleton account map.
     * This is intended to run first in the trigger execution order.
     */
    public class Service implements TriggerAction {
        public void execute(List<SObject> records) {
            Set<Id> accountIds = new Set<Id>();
            for (SObject rec : records) {
                Contact c = (Contact)rec;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }

            if (!accountIds.isEmpty()) {
                TA_Contact_Queries queries = TA_Contact_Queries.getInstance();
                // Reload the map on every execution to ensure fresh data for this batch
                queries.accountsById = new Map<Id, Account>([
                    SELECT BillingStreet, BillingCity, BillingPostalCode, BillingCountry, AccountSource
                    FROM Account
                    WHERE Id IN :accountIds
                ]);
            }
        }
    }
}
