        Map<Id, Account> accounts = TA_Contact_Queries.getInstance().accountsById;

        for (SObject rec : records) {
            Contact c = (Contact)rec;

            // Only proceed if the contact has an account and all mailing address fields are blank
            if (c.AccountId != null && 
                String.isBlank(c.MailingStreet) && 
                String.isBlank(c.MailingCity) && 
                String.isBlank(c.MailingPostalCode) && 
                String.isBlank(c.MailingCountry)) {

                Account acc = accounts.get(c.AccountId);
                if (acc != null) {
                    c.MailingStreet = acc.BillingStreet;
                    c.MailingCity = acc.BillingCity;
                    c.MailingPostalCode = acc.BillingPostalCode;
                    c.MailingCountry = acc.BillingCountry;
                }
            }
        }
    }
